// Some portions generated by Claude
export function coincidentCards(count = 237) {
  return {revision: 1, nodes: Array.from({length: count}, (_, i) => ({id: String(i),
    label: 'A long node label that needs its full measured width ' + i, kind: 'iri', x: 0, y: 0, pinned: i === 0})), edges: []};
}

export function wideGrid(count = 1600) {
  // 64 units of horizontal card clearance: clear under the roomier policy too.
  return {revision: 1, nodes: Array.from({length: count}, (_, i) => ({id: String(i),
    label: 'A long literal displayed across the full measured node width ' + i, kind: 'literal',
    x: (i % 40) * 344 + 17, y: Math.floor(i / 40) * 120 + 13})), edges: []};
}

export function groupedNetwork(groupCount = 4, size = 12) {
  const nodes = [], edges = [], groups = [];
  const link = (a, b) => edges.push({id: String(edges.length), source: String(a), target: String(b), predicate: 'urn:related', label: 'related'});
  for (let c = 0; c < groupCount; c++) {
    const nodeIds = [];
    for (let i = 0; i < size; i++) {
      const id = String(c * size + i); nodeIds.push(id);
      nodes.push({id, label: `Group ${c} resource ${i} with a descriptive name`, kind: 'iri', x: i * 15, y: c * 20});
      if (i) link(c * size + i - 1, c * size + i);
      if (i > 1) link(c * size + i - 2, c * size + i);
    }
    groups.push({id: `g${c}`, nodeIds});
    if (c) for (let i = 0; i < size; i += 3) link((c - 1) * size + i, c * size + i);
  }
  return {graph: {nodes, edges, revision: 1}, groups};
}
